package clyvr.view;
import clyvr.controller.*;import clyvr.model.Entities.*;import clyvr.ui.*;import javax.swing.*;import java.awt.*;import java.util.*;
public class DoctorManagementView extends JPanel {
 public DoctorManagementView(AppController app){super(new BorderLayout());JPanel p=ViewSupport.page("Doctors  >  Doctor Management","DEMO ONLY — changes are stored in local session data, not in the backend.");JButton back=Theme.secondary("← Back to Doctors");back.setAlignmentX(Component.LEFT_ALIGNMENT);back.addActionListener(e->app.navigate("Doctors"));p.add(back);Theme.space(p,12);JButton add=Theme.button("+ Add demo doctor");add.addActionListener(e->{JTextField first=Theme.field(),last=Theme.field();JComboBox<String> specialty=new JComboBox<>(clyvr.model.ClinicStore.SERVICES);JPanel form=new JPanel(new GridLayout(0,1,3,5));form.add(new JLabel("First name"));form.add(first);form.add(new JLabel("Last name"));form.add(last);form.add(new JLabel("Specialty"));form.add(specialty);if(JOptionPane.showConfirmDialog(this,form,"Add demo doctor",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){if(first.getText().isBlank()||last.getText().isBlank()){app.error("Doctor name is required.");return;}Doctor d=app.store.addDoctor(first.getText().trim(),last.getText().trim(),(String)specialty.getSelectedItem());app.info("Added "+app.store.doctorName(d.id)+". Demo username: "+app.store.user(d.userId).username+" / Demo password: doctor123");app.refresh();}});p.add(add);Theme.space(p,17);
  for(Doctor d:new ArrayList<>(app.store.doctors)){JButton remove=Theme.secondary("Remove demo doctor");remove.addActionListener(e->{if(!app.confirm("Remove "+app.store.doctorName(d.id)+" from this local demo session?"))return;try{app.store.removeDoctor(d.id);app.info("Demo doctor removed from this session.");app.refresh();}catch(Exception ex){app.error(ex.getMessage());}});ViewSupport.line(p,app.store.doctorName(d.id),d.specialty,remove);}add(ViewSupport.wrap(p));}
}
